      "id": "16-the-algorithm-the-ladder-is-gone",
      "title": "The Algorithm (The Ladder is Gone)",
      "act": "Act IV: The Slaughter (2025–Present)",
      "actNumber": 4,
      "audioFile": "assets/audio/16-the-algorithm-the-ladder-is-gone.mp3",
